import test from 'node:test';import assert from 'node:assert/strict';import {createBoardFlow} from '../src/pixi/board-flow.js';import {productionBoardFlowOptions} from '../src/app/production-board-profile.js';import {sourceBoardSurfaces} from '../src/pixi/source-board-surfaces.js';import {installRearElectricDecoration} from '../src/pixi/rear-electric-decoration.js';
const base=()=>{const p=createBoardFlow({lcd:true,...productionBoardFlowOptions()}).flow.physics,path=p.sourceGuidePaths.find(p=>p.id==='electric-left-moulding');delete path.contactRole;delete path.depthPlane;for(const c of p.colliders)if(c.sourceGuideId===path.id){delete c.active;delete c.contactRole;delete c.depthPlane;}delete p.electricDecorationProfile;return p;};
test('rear decoration keeps every rendered surface, trace point, pin and mouth while disabling only its authored contacts',()=>{const p=base(),art=sourceBoardSurfaces(p),pins=structuredClone(p.pins),points=structuredClone(p.sourceGuidePaths.map(p=>p.points)),other=JSON.stringify(p.colliders.filter(c=>c.sourceGuideId!=='electric-left-moulding'));installRearElectricDecoration(p);assert.deepEqual(sourceBoardSurfaces(p),art);assert.deepEqual(p.pins,pins);assert.deepEqual(p.sourceGuidePaths.map(p=>p.points),points);assert.equal(JSON.stringify(p.colliders.filter(c=>c.sourceGuideId!=='electric-left-moulding')),other);const removed=p.colliders.filter(c=>c.sourceGuideId==='electric-left-moulding');assert.equal(removed.length,p.sourceGuidePaths.find(p=>p.id==='electric-left-moulding').worldPoints.length-1);assert.ok(removed.every(c=>c.active===false&&c.contactRole==='rear-decoration'));assert.equal(p.pockets.find(p=>p.kind==='start').w,16);});
test('front ball crosses the former electric edge instead of resting on rear decoration',()=>{const simulate=rear=>{const p=base();if(rear)installRearElectricDecoration(p);p.colliders=p.colliders.filter(c=>c.sourceGuideId==='electric-left-moulding');p.pins=[];p.mechanisms=[];p.sourceStage=null;const b={id:1,x:565.953*.5-14,y:822.261*.5+120,vx:0,vy:0,r:3,omega:0,hits:0,contactCount:0,leftLaunchPlane:true,sourceStageSpilled:true};for(let i=0;i<1200;i++)p.advanceBall(b,1/1200);return (b.y-120)*2;};assert.ok(simulate(false)<830);assert.ok(simulate(true)>1000);});
